typedef unsigned char u_char;
typedef unsigned int u_int;
typedef unsigned int size_t;

struct nglFileBuf
{
  u_char* Buf;
  u_int Size;
  u_int UserData;
};

struct nglSystemCallbackStruct
{
  bool (*ReadFile)( const char* FileName, nglFileBuf* File, u_int Align );
  void (*ReleaseFile)( nglFileBuf* File );
  void (*CriticalError)( const char* Text );
  void (*DebugPrint)( const char* Text );
  void* (*MemAlloc)( u_int Size, u_int Align );
  void (*MemFree)( void* Ptr );
};

extern nglSystemCallbackStruct nglSystemCallbacks;
extern const char* nglHostPrefix;
extern "C" int strncmp( const char*, const char*, size_t );
extern "C" size_t strlen( const char* );
extern "C" char* strcpy( char*, const char* );
extern "C" char* strcat( char*, const char* );
extern "C" int sceOpen( const char*, int, ... );
extern "C" int sceLseek( int, int, int );
extern "C" int sceRead( int, void*, int );
extern "C" int sceClose( int );
extern void* nglMemAlloc( u_int Size, u_int Align );

enum
{
  SCE_RDONLY = 1,
  SCE_SEEK_SET = 0,
  SCE_SEEK_END = 2
};

bool nglReadFile( const char* FileName, nglFileBuf* File, u_int Align )
{
  if ( nglSystemCallbacks.ReadFile )
    return nglSystemCallbacks.ReadFile( FileName, File, Align );
  else
  {
    static char Work[256];

    if ( strncmp( FileName, nglHostPrefix, strlen( nglHostPrefix ) ) == 0 )
      strcpy( Work, "" );
    else
      strcpy( Work, nglHostPrefix );
    strcat( Work, FileName );

    int fd = sceOpen( Work, SCE_RDONLY );
    if ( fd < 0 )
      return false;

    File->Size = sceLseek( fd, 0, SCE_SEEK_END );
    sceLseek( fd, 0, SCE_SEEK_SET );

    // sceRead only reads in 32-byte chunks, rounding down, so we need to read in the extra on our own.
    File->Buf = (u_char*)nglMemAlloc( ( File->Size + 31 ) & ~31, 128 );
    sceRead( fd, File->Buf, ( File->Size + 31 ) & ~31 );
    sceClose( fd );

    return true;
  }
}
